async function REACTOR_F(arg = false) {
  if (arg || isVerb(V.EXAMINE, V.ANALYZE)) {
    if ((g.P_ADVERB == W.CAREFULLY) && !arg) {
      tell(S(getProp(LOCAL_SUB, P.TEXT)), "\n");
      return true;
    } else if (arg && hasFlag(REACTOR, ONBIT) && !(hasFlag(REACTOR, OPENBIT))) {
      return true;
    } else {
      tell("The power reactor is o", S((hasFlag(REACTOR, ONBIT) ? "n" : "ff")), " and ", S((hasFlag(REACTOR, OPENBIT) ? "open" : "closed")), ".\n");
      return true;
    }
  } else if (isVerb(V.LAMP_ON)) {
    if (hasFlag(REACTOR, ONBIT)) {
      return (await ALREADY(REACTOR, "on"));
    } else if (!(loc(CATALYST_CAPSULE) == REACTOR)) {
      clearFlag(CATALYST_CAPSULE, NDESCBIT);
      return await TELL_HINT(33, CATALYST_CAPSULE, false);
    } else if (hasFlag(REACTOR, OPENBIT)) {
      return (await YOU_CANT("start", false, "open"));
    } else {
      setFlag(REACTOR, ONBIT);
      tell("Electrical systems now activated.\n");
      await SCORE_OBJ(REACTOR);
      return true;
    }
  } else if (isVerb(V.LAMP_OFF)) {
    if (!(hasFlag(REACTOR, ONBIT))) {
      return (await ALREADY(REACTOR, "off"));
    } else if (hasFlag(ENGINE, ONBIT)) {
      tell("You can't turn it off while the engine is on.\n");
      return true;
    } else {
      clearFlag(REACTOR, ONBIT);
      tell("Electrical systems now de-activated.\n");
      return true;
    }
  } else if (isVerb(V.OPEN) && hasFlag(REACTOR, ONBIT)) {
    return (await YOU_CANT("open", false, "turned on"));
  } else {
    return false;
  }
}

