async function THROTTLE_F() {
  let th = 0;
  if (isVerb(V.OPEN, V.PUSH, V.LAMP_ON)) {
    g.P_NUMBER = 1 + g.THROTTLE_SETTING;
    if (g.P_NUMBER > THROTTLE_MAX) {
      tell("You're going as fast as you can!\n");
      return true;
    } else {
      await PERFORM(V.SET, THROTTLE);
      return true;
    }
  } else if (isVerb(V.CLOSE, V.LAMP_OFF)) {
    if (g.THROTTLE_SETTING == 0) {
      (await ALREADY(THROTTLE, "closed"));
      return true;
    }
    g.THROTTLE_SETTING = 0;
    if (g.SUB_IN_TANK || g.SUB_IN_DOME) {
      tell("The throttle is now closed. You must open it to make the ", D(SUB), " go anywhere.\n");
    } else {
      tell("The ", D(SUB), " slows to a halt.\n");
      await COOL_BACK();
    }
    return true;
  } else if (isVerb(V.MOVE, V.TURN)) {
    tell("Set it to the speed you want: fast, medium, slow, or off.\n");
    return true;
  } else if (isVerb(V.ANALYZE, V.EXAMINE, V.READ)) {
    tell("The throttle is set to ", S(get(g.THROTTLE_DESCS, g.THROTTLE_SETTING)), ".\n");
    return true;
  } else if (isVerb(V.SET, V.PUT, V.MOVE_DIR) && (g.PRSO == THROTTLE)) {
    if ((g.PRSI == FAST) || (g.PRSI == MEDIUM || g.PRSI == SLOW || g.PRSI == OFF)) {
      if (g.PRSI == OFF) {
        th = 0;
      } else if (g.PRSI == SLOW) {
        th = 1;
      } else if (g.PRSI == MEDIUM) {
        th = 2;
      } else if (g.PRSI == FAST) {
        th = 3;
      }
    } else if ((g.PRSI == false || g.PRSI == GRID_UNIT) && (g.P_NUMBER > (-1)) && !(g.P_NUMBER > THROTTLE_MAX)) {
      th = g.P_NUMBER;
    } else {
      tell("Set it off, slow, medium, or fast.\n");
      return true;
    }
    if (th == 0) {
      tell(S(g.I_ASSUME), " close the ", D(THROTTLE), ".)\n");
      await PERFORM(V.CLOSE, THROTTLE);
      return true;
    }
    if (!(hasFlag(ENGINE, ONBIT))) {
      tell("Nothing happens when you open the throttle. ");
      if (g.GATE_CRASHED) {
        tell("The turbine was stopped by Automatic Shutoff when you crashed into the sea gate.");
      } else {
        tell("The engine is off.");
      }
      await THIS_IS_IT(ENGINE);
      crlf();
    } else if (g.SUB_IN_TANK) {
      if (await HATCH_GATE_NOT_READY$(TANK_GATE)) {
        return true;
      }
      if (g.JOYSTICK_DIR == P.EAST) {
        if (!(hasFlag(TANK_GATE, OPENBIT))) {
          (await GATE_CRASH("open", THROTTLE, TANK_GATE));
        } else {
          g.THROTTLE_SETTING = th;
          await SUB_LEAVES(true, P.EAST);
        }
      } else {
        g.THROTTLE_SETTING = th;
        await OKAY_THROTTLE(P.EAST);
      }
    } else if (g.SUB_IN_DOME) {
      if (await HATCH_GATE_NOT_READY$(AIRLOCK_HATCH)) {
        return true;
      }
      g.THROTTLE_SETTING = th;
      if (g.JOYSTICK_DIR == P.SOUTH) {
        await SUB_LEAVES(false, P.SOUTH);
      } else {
        await OKAY_THROTTLE(P.SOUTH);
      }
    } else {
      if (g.THROTTLE_SETTING == th) {
        tell("Okay, you're still ");
      } else {
        if (g.THROTTLE_SETTING < th) {
          tell("You feel the seat press ");
          if (!(g.THROTTLE_SETTING == 0)) {
            tell("harder ");
          }
          tell("against you, and the ", D(ENGINE), " gets loud");
        } else {
          tell("The ", D(ENGINE), " gets quiet");
        }
        tell("er. You're now ");
      }
      tell("travelling at a speed of ", N(th), " ", D(GRID_UNIT));
      if (!(1 == th)) {
        tell("s");
      }
      g.THROTTLE_SETTING = th;
      tell(" per turn.\n");
    }
    return true;
  } else {
    return false;
  }
}

