async function DEPTH_CONTROL_F() {
  let dep = 0, new_diving$ = 0;
  if (await REMOTE_VERB$()) {
    return false;
  } else if (g.SUB_IN_TANK) {
    (await YOU_CANT("submerge", SUB, "here"));
    return true;
  } else if (g.SUB_IN_DOME && (await WHY_NEED(DEPTH_CONTROL, AIRLOCK))) {
    return true;
  } else if (isVerb(V.ANALYZE, V.EXAMINE, V.READ, V.WHAT)) {
    tell("It's set for a desired depth of ", N(5 * g.TARGET_DEPTH), " meters.\n");
    return true;
  } else if (isVerb(V.SET)) {
    dep = g.P_NUMBER;
    if (hasFlag(AUTO_PILOT, ONBIT)) {
      tell("Let the ", D(AUTO_PILOT), " handle that.\n");
      return true;
    } else if (!(hasFlag(DEPTHFINDER, ONBIT))) {
      await THIS_IS_IT(DEPTHFINDER);
      tell("You'd better turn on the ", D(DEPTHFINDER), " first.\n");
      return true;
    } else if (!(dep > (-1))) {
      tell("You must set it to at least zero!\n");
      return true;
    } else if (g.SUB_IN_BATTLE && (g.SUB_DEPTH > dep)) {
      tell("If you go above the Snark, Thorpe will shoot you!\n");
      return true;
    } else if ((dep > 0) && hasFlag(SUB_DOOR, OPENBIT)) {
      (await YOU_CANT("submerge", SUB_DOOR, "open"));
      return true;
    } else if (g.PRSI == METER) {
      dep = div(2 + dep, 5);
      if (!(g.P_NUMBER == (5 * dep))) {
        tell("(That rounds off to ", N(5 * dep), " meters.)\n");
      }
    }
    g.TARGET_DEPTH = dep;
    if (!(dep == 0)) {
      g.EVER_SUBMERGED$ = true;
    }
    if (g.SUB_DEPTH == dep) {
      if (g.DIVING$ == 0) {
        (await ALREADY(PLAYER, "at that depth"));
      } else {
        tell("Your ", S((1 == g.DIVING$ ? "de" : "a")), "scent ceases.");
      }
      crlf();
      g.DIVING$ = 0;
      return true;
    } else {
      if (g.SUB_DEPTH < g.TARGET_DEPTH) {
        new_diving$ = 1;
      } else {
        new_diving$ = -1;
      }
      if (!(g.DIVING$ == new_diving$)) {
        tell("The ", D(SUB), " noses ");
        if (new_diving$ == 1) {
          tell("down");
        } else {
          tell("up");
        }
        tell("ward");
        if (g.SUB_DEPTH == 0) {
          tell(", and ", D(GLOBAL_WATER), " begins to wash over your forward ", D(SUB_WINDOW));
        }
        tell(". You're now ");
      } else {
        tell("Okay, you're still ");
      }
      g.DIVING$ = new_diving$;
      if (1 == g.DIVING$) {
        tell("div");
      } else {
        tell("ris");
      }
      tell("ing at a speed of 5 meters per ");
      if (g.THROTTLE_SETTING == 0) {
        tell("turn.\n");
        return true;
      } else {
        tell(D(GRID_UNIT), ".\n");
        return true;
      }
    }
  } else {
    return false;
  }
}

