async function THORPE_SHOOT$(x, y) {
  if (g.SNARK_TRANKED) {
    return await FORWARD_OF_THORPE$(x, y);
  } else {
    return (await STARBOARD_OF_THORPE$(x, y)) && (await FORWARD_OF_THORPE$(x, y));
  }
}

async function STARBOARD_OF_THORPE$(x, y) {
  if (!(0 > ((g.THORPE_HLAT * (x - g.THORPE_LON)) - (g.THORPE_HLON * (y - g.THORPE_LAT))))) {
    return true;
  } else {
    return false;
  }
}

async function FORWARD_OF_THORPE$(x, y) {
  if (!(0 > ((g.THORPE_HLON * (x - g.THORPE_LON)) - (g.THORPE_HLAT * (g.THORPE_LAT - y))))) {
    return true;
  } else {
    return false;
  }
}

async function THORPE_POS$(lon, lat) {
  if (!(g.SUB_DEPTH == AIRLOCK_DEPTH)) {
    return false;
  } else if ((lat == (g.THORPE_LAT - g.THORPE_HLAT)) && (lon == (g.THORPE_LON - g.THORPE_HLON))) {
    return true;
  } else if ((lat == g.THORPE_LAT) && (lon == g.THORPE_LON)) {
    return true;
  } else {
    return false;
  }
}

async function SNARK_POS$(lon, lat) {
  return (await SNARK_HEAD_POS$(lon, lat)) || (await SNARK_TAIL_POS$(lon, lat));
}

async function SNARK_HEAD_POS$(lon, lat) {
  if (!(g.SUB_DEPTH == AIRLOCK_DEPTH)) {
    return false;
  } else if ((lat == g.SNARK_LAT) && (lon == g.SNARK_LON)) {
    return true;
  } else {
    return false;
  }
}

async function SNARK_TAIL_POS$(lon, lat) {
  let x = 0, y = 0, hlon = 0, hlat = 0;
  if (!(g.SUB_DEPTH == AIRLOCK_DEPTH)) {
    return false;
  } else if (g.SNARK_TRANKED) {
    hlon = g.SNARK_HLON;
    hlat = g.SNARK_HLAT;
  } else {
    hlon = g.THORPE_HLON;
    hlat = g.THORPE_HLAT;
  }
  x = g.SNARK_LON - hlon;
  y = g.SNARK_LAT - hlat;
  if ((lat == y) && (lon == x)) {
    return true;
  }
  x = x - hlon;
  y = y - hlat;
  if ((lat == y) && (lon == x)) {
    return true;
  }
  if ((lat == (y - hlat)) && (lon == (x - hlon))) {
    return true;
  } else {
    return false;
  }
}

