async function I_UPDATE_THORPE() {
  let dlat = 0, dlon = 0, z = 0;
  if (g.SUB_IN_BATTLE) {
    z = g.THORPE_HLON * g.THORPE_HLAT;
    if (!(await THORPE_SHOOT$(g.SUB_LON, g.SUB_LAT))) {
      if ((g.THORPE_DLON == 0) && (g.THORPE_DLAT == 0)) {
        g.THORPE_TURNING$ = !g.THORPE_TURNING$;
        if (g.THORPE_TURNING$) {
        } else if (await STARBOARD_OF_THORPE$(g.SUB_LON, g.SUB_LAT)) {
          if (g.THORPE_HLON == 0) {
            g.THORPE_HLON = g.THORPE_HLAT;
          } else if ((-1) == z) {
            g.THORPE_HLON = 0;
          } else if (1 == z) {
            g.THORPE_HLAT = 0;
          } else {
            g.THORPE_HLAT = -g.THORPE_HLON;
          }
        } else {
          if (g.THORPE_HLON == 0) {
            g.THORPE_HLON = -g.THORPE_HLAT;
          } else if ((-1) == z) {
            g.THORPE_HLAT = 0;
          } else if (1 == z) {
            g.THORPE_HLON = 0;
          } else {
            g.THORPE_HLAT = g.THORPE_HLON;
          }
        }
      } else {
        g.THORPE_DLON = 0;
        g.THORPE_DLAT = 0;
      }
    } else {
      tell("Thorpe zeroed in on you and fired his rocket! It streaks through the water toward the ", D(SUB), "! In an instant your sub will be just twisted metal, trapping you and Tip forever in Davy Jones's locker!");
      await FINISH();
    }
  }
  g.THORPE_LON = g.THORPE_LON + g.THORPE_DLON;
  g.THORPE_LAT = g.THORPE_LAT + g.THORPE_DLAT;
  z = g.THORPE_HLON * g.THORPE_HLAT;
  if (z == 0) {
    if (g.THORPE_HLAT == 0) {
      g.SNARK_LAT = g.THORPE_LAT + g.THORPE_HLON;
      g.SNARK_LON = g.THORPE_LON + g.THORPE_HLON;
    } else {
      g.SNARK_LAT = g.THORPE_LAT + g.THORPE_HLAT;
      g.SNARK_LON = g.THORPE_LON - g.THORPE_HLAT;
    }
  } else if ((-1) == z) {
    g.SNARK_LON = g.THORPE_LON + g.THORPE_HLON;
    g.SNARK_LAT = g.THORPE_LAT;
  } else if (1 == z) {
    g.SNARK_LAT = g.THORPE_LAT + g.THORPE_HLAT;
    g.SNARK_LON = g.THORPE_LON;
  }
  return false;
}

