async function WEAPON_F(obj) {
  let which = 0, o = 0, not_on_sub = false, someone = false;
  if (await BAD_AIR$()) {
    return true;
  } else if (isVerb(V.FIND, V.SEARCH_FOR, V.TAKE)) {
  } else if (await MOUNTING_VERB$(obj)) {
  } else if (await REMOTE_VERB$()) {
    return false;
  }
  if (obj == DART) {
    which = 1;
  }
  if (!(obj == get(g.ON_SUB, which))) {
    not_on_sub = true;
  }
  if (!g.SUB_IN_DOME && not_on_sub) {
    tell("You can't use");
    await PRINTT(obj);
    tell(" now!\n");
    return true;
  }
  if (not_on_sub) {
    if (isVerb(V.FIND, V.SEARCH_FOR)) {
      if ((g.HERE == loc(obj)) && !(hasFlag(obj, TOUCHBIT))) {
        clearFlag(obj, NDESCBIT);
        (await HE_SHE_IT(g.WINNER, true, "find"));
        tell(" it among lots of equipment and supplies.\n");
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.TAKE)) {
      if (which == 1) {
        clearFlag(DART, NDESCBIT);
        if (hasFlag(DART, MUNGBIT)) {
          return await NO_GOOD_MUNGED();
        } else {
          return false;
        }
      } else {
        return false;
      }
    } else if (await MOUNTING_VERB$(obj)) {
      if (!(g.WINNER == PLAYER)) {
        someone = g.WINNER;
      } else if (someone = await FIND_FLAG(g.HERE, PERSON, PLAYER)) {
      }
      if (!someone) {
        if (!(g.HERE == (await META_LOC(obj)))) {
          await NOT_HERE(obj);
          return true;
        } else if (!(g.HERE == AIRLOCK)) {
          await NOT_HERE(CLAW);
          return true;
        }
      }
      if (which == 0) {
        if (someone && !(g.HERE == AIRLOCK)) {
          tell("\"Good idea! That should stop the ", D(SNARK), "! It could disable an enemy sub, too! Shall I ");
          if (isVerb(V.PUT)) {
            tell("do it");
          } else {
            tell("have it mounted");
            if (!(g.PRSI == CLAW)) {
              tell(" on an ", D(CLAW), " of the ", D(SUB));
            }
          }
          tell("?\"");
          if (await YES$()) {
            await MOUNT_WEAPON(BAZOOKA);
            await FINE_SEQUENCE();
          }
          return true;
        } else {
          await MOUNT_WEAPON(BAZOOKA);
          (await OKAY(BAZOOKA, "mounted"));
          await FINE_SEQUENCE();
          return true;
        }
      } else if (hasFlag(DART, MUNGBIT)) {
        return await NO_GOOD_MUNGED();
      } else {
        await MOUNT_WEAPON(DART);
        if (someone && !(g.HERE == AIRLOCK)) {
          tell(D(someone), " promptly mounts the ", D(DART), " on an ", D(CLAW), ".\n");
        } else {
          (await OKAY(DART, "mounted"));
        }
        if (BAZOOKA == get(g.ON_SUB, 0)) {
          await FINE_SEQUENCE();
        }
        return true;
      }
    } else {
      return false;
    }
  } else {
    if (isVerb(V.FIND, V.EXAMINE)) {
      tell("It's mounted on one of the ", D(SUB), "'s ", D(CLAW), "s.\n");
      return true;
    } else if (isVerb(V.TAKE) || (await MOUNTING_VERB$(obj))) {
      tell("You'd better leave it mounted on the ", D(CLAW), ".\n");
      return true;
    } else if (await REMOTE_VERB$()) {
      return false;
    } else if (isVerb(V.MOVE, V.MOVE_DIR)) {
      tell("You should type where you want to aim it.\n");
      return true;
    } else if (isVerb(V.AIM)) {
      if (hasFlag(CLAW, MUNGBIT)) {
        tell("Nothing happens. Either the ", D(CLAW), " or the ", D(obj), " was damaged when you rammed the ", D(SNARK), "!\n");
        return true;
      } else if (g.PRSI == GLOBAL_THORPE || g.PRSI == THORPE_SUB) {
        if (!(await STARBOARD_OF_THORPE$(g.SUB_LON, g.SUB_LAT))) {
          (await YOU_CANT("aim", GLOBAL_SNARK, "in the way"));
          return true;
        } else {
          if (g.SUB_IN_BATTLE) {
            await SCORE_OBJ(THORPE_SUB);
          }
          put(g.OBJ_AIMED_AT, which, THORPE_SUB);
          put(g.LON_AIMED_AT, which, g.THORPE_LON);
          put(g.LAT_AIMED_AT, which, g.THORPE_LAT);
        }
      } else if (g.PRSI == GLOBAL_SNARK || g.PRSI == SNARK) {
        put(g.OBJ_AIMED_AT, which, SNARK);
        put(g.LON_AIMED_AT, which, g.SNARK_LON);
        put(g.LAT_AIMED_AT, which, g.SNARK_LAT);
      } else {
        return false;
      }
      tell("Aimed.\n");
      return true;
    } else if (isVerb(V.SHOOT, V.KILL, V.ATTACK)) {
      o = get(g.OBJ_AIMED_AT, which);
      if (get(g.ALREADY_SHOT, which)) {
        tell("You already shot");
        await THE_PRSI_PRINT();
        tell("!\n");
        return true;
      } else if (!o) {
        tell("You have to aim it first!\n");
        return true;
      }
      if (((THORPE_SUB == o) && !(g.PRSO == GLOBAL_THORPE || g.PRSO == THORPE_SUB)) || ((SNARK == o) && !(g.PRSO == GLOBAL_SNARK || g.PRSO == SNARK))) {
        tell("You didn't aim it at");
        await THE_PRSO_PRINT();
        tell(".\n");
        return true;
      }
      if (g.PRSO == GLOBAL_THORPE || g.PRSO == THORPE_SUB) {
        if (eq(get(g.LON_AIMED_AT, which), g.THORPE_LON) && eq(get(g.LAT_AIMED_AT, which), g.THORPE_LAT)) {
          put(g.ALREADY_SHOT, which, true);
          if (which == 0) {
            return await MUNG_TARGET();
          } else {
            tell("Fudge! Your tranquilizer dart hit the ", D(THORPE_SUB), ", and its metal hull can't be put to sleep! Tough luck, ");
            await PRINT_NAME(g.FIRST_NAME);
            tell(".\n");
            return true;
          }
        } else {
          await TOO_BAD_BUT(g.PRSO);
          tell(" moved since you aimed.\n");
          return true;
        }
      } else if (g.PRSO == GLOBAL_SNARK || g.PRSO == SNARK) {
        if (eq(get(g.LON_AIMED_AT, which), g.SNARK_LON) && eq(get(g.LAT_AIMED_AT, which), g.SNARK_LAT)) {
          put(g.ALREADY_SHOT, which, true);
          g.SNARK_TRANKED = true;
          g.SNARK_HLON = g.THORPE_HLON;
          g.SNARK_HLAT = g.THORPE_HLAT;
          if (which == 0) {
            tell("KA-VOOOM! The ", D(SNARK), " shudders and stops moving! You scored a clean hit with your ", D(BAZOOKA), "!\n");
            await TIP_SAYS();
            tell("Rats! There goes our safety shield!\" And he's right. Even though you've saved the ", D(AQUADOME), " from further danger of monster attack, the ", D(SUB), " is now exposed to the ", D(THORPE_SUB), "'s rocket weapon!\n");
            return true;
          } else {
            tell("Right on! The dart hits the ", D(SNARK), " and sticks out of its side. The tranquilizer spreads through the ", D(SNARK), ", sending it to Slumberland.\nBut this may have been a bad move. With the ", D(SNARK), " fast asleep, its huge body can't hide you from the ", D(THORPE_SUB), "'s rocket attack!\n");
            return true;
          }
        } else {
          await TOO_BAD_BUT(g.PRSO);
          tell(" moved since you aimed.\n");
          return true;
        }
      } else {
        return false;
      }
    } else {
      return false;
    }
  }
}

