async function MOUNT_WEAPON(obj) {
  if (obj == BAZOOKA) {
    await SCORE_OBJ(BLY);
    putProp(BAZOOKA, P.LDESC, "The bazooka is mounted on a claw.");
    if (!(getProp(BAZOOKA, P.VALUE) == 0)) {
      tell("\"Of course I'll have to get it first.\"\n");
      await SCORE_OBJ(BAZOOKA);
    }
    await MOUNT(0, BAZOOKA);
  } else if (obj == DART) {
    putProp(DART, P.LDESC, "The dart is mounted on a claw.");
    await SCORE_OBJ(HORVAK);
    await MOUNT(1, DART);
  } else if (get(g.ON_SUB, 0)) {
    if (get(g.ON_SUB, 1)) {
      tell("The claws are holding all they can.\n");
      return false;
    } else {
      put(g.ON_SUB, 1, obj);
    }
  } else {
    put(g.ON_SUB, 0, obj);
  }
  if (g.HERE == SUB || g.HERE == CRAWL_SPACE) {
    move(obj, SUB);
  } else if (g.SUB_IN_DOME) {
    move(obj, AIRLOCK);
  } else {
    move(obj, NORTH_TANK_AREA);
  }
  setFlag(obj, NDESCBIT);
  clearFlag(obj, TAKEBIT);
  return setFlag(obj, TRYTAKEBIT);
}

async function FINE_SEQUENCE() {
  if (!g.TIP_FOLLOWS_YOU$) {
    return false;
  } else if (await READY_FOR_SNARK$()) {
    return false;
  }
  await MOVE_HERE_NOT_SUB(BLY);
  tell("\"Are you ready to take off now, ");
  await PRINT_NAME(g.FIRST_NAME);
  tell("?\" Zoe Bly ", S((loc(BLY) == g.HERE ? "ask" : "shout")), "s anxiously.");
  if (!(await YES$())) {
    return false;
  }
  tell("\"Wait!\" Tip cuts in. ");
  g.WINNER = PLAYER;
  return await PERFORM(V.ASK_ABOUT, TIP, FINE_GRID);
}

