async function NOT_HERE_OBJECT_F() {
  let tbl = 0, prso$ = true, obj = 0;
  if ((g.PRSO == NOT_HERE_OBJECT) && (g.PRSI == NOT_HERE_OBJECT)) {
    tell("(Those things aren't here!)\n");
    return M_FATAL;
  } else if (g.PRSO == NOT_HERE_OBJECT) {
    tbl = g.P_PRSO;
  } else {
    tbl = g.P_PRSI;
    prso$ = false;
  }
  if (isVerb(V.ASK_ABOUT, V.ASK_FOR, V.SEARCH_FOR) && hasFlag(g.PRSO, PERSON) && (loc(g.PRSO) == GLOBAL_OBJECTS)) {
    tell(D(g.PRSO));
    await NOT_HERE_PERSON(g.PRSO);
  }
  if (prso$) {
    if ((g.PRSA == V.ASK_CONTEXT_ABOUT || g.PRSA == V.BOARD) || (g.PRSA == V.ASK_CONTEXT_FOR || g.PRSA == V.TAKE_WITH) || (g.PRSA == V.FIND || g.PRSA == V.FOLLOW || g.PRSA == V.USE) || (g.PRSA == V.LEAVE || g.PRSA == V.DISEMBARK || g.PRSA == V.PHONE) || (g.PRSA == V.THROUGH || g.PRSA == V.WALK_TO || g.PRSA == V.WHAT) || ((g.PRSA == V.BRING || g.PRSA == V.TAKE || g.PRSA == V.SSHOW) && !(g.WINNER == PLAYER))) {
      if (obj = await FIND_NOT_HERE(tbl, prso$)) {
        if (!(obj == NOT_HERE_OBJECT)) {
          return M_FATAL;
        }
      } else {
        return false;
      }
    }
  } else {
    if ((g.PRSA == V.ASK_ABOUT || g.PRSA == V.ASK_FOR || g.PRSA == V.TAKE_TO) || (g.PRSA == V.SEARCH_FOR || g.PRSA == V.TELL_ABOUT) || ((g.PRSA == V.SBRING || g.PRSA == V.SHOW) && !(g.WINNER == PLAYER))) {
      if (obj = await FIND_NOT_HERE(tbl, prso$)) {
        if (!(obj == NOT_HERE_OBJECT)) {
          return M_FATAL;
        }
      } else {
        return false;
      }
    }
  }
  tell("(You can't see any");
  await NOT_HERE_PRINT();
  tell(" here!)\n");
  return M_FATAL;
}

async function FIND_NOT_HERE(tbl, prso$) {
  let m_f = 0, obj = 0, person$ = true;
  m_f = await MOBY_FIND(tbl);
  if (g.DEBUG) {
    tell("[Found ", N(m_f), " objects]\n");
  }
  if (1 == m_f) {
    if (g.DEBUG) {
      tell("[Namely: ", D(g.P_MOBY_FOUND), "]\n");
    }
    if (prso$) {
      g.PRSO = g.P_MOBY_FOUND;
    } else {
      g.PRSI = g.P_MOBY_FOUND;
    }
    return false;
  } else if ((1 < m_f) && (obj = await apply(getProp(obj = get(tbl, 1), P.GENERIC), obj))) {
    if (g.DEBUG) {
      tell("[Generic: ", D(obj), "]\n");
    }
    if (obj == NOT_HERE_OBJECT) {
      return true;
    } else if (prso$) {
      g.PRSO = obj;
    } else {
      g.PRSI = obj;
    }
    return false;
  } else if ((!prso$ && (loc(g.PRSO) == g.HERE) && isVerb(V.ASK_ABOUT, V.ASK_FOR, V.TELL_ABOUT)) || (prso$ && (await QCONTEXT_GOOD$()) && isVerb(V.ASK_CONTEXT_ABOUT, V.ASK_CONTEXT_FOR)) || (!(g.WINNER == PLAYER) && isVerb(V.FIND, V.WHAT, V.GIVE, V.SGIVE))) {
    if (isVerb(V.ASK_ABOUT, V.ASK_FOR)) {
      if (!(hasFlag(g.PRSO, PERSON))) {
        person$ = false;
        tell("The ");
      }
      tell(D(g.PRSO));
    } else if (await QCONTEXT_GOOD$()) {
      if (!(hasFlag(g.QCONTEXT, PERSON))) {
        person$ = false;
        tell("The ");
      }
      tell(D(g.QCONTEXT));
    } else if (!(g.WINNER == PLAYER)) {
      tell(D(g.WINNER));
    } else if (obj = await FIND_FLAG(g.HERE, PERSON, PLAYER)) {
      tell(D(obj));
    } else if (await VISIBLE$(TIP)) {
      tell("Tip");
    } else {
      tell("Someone");
    }
    if (!person$) {
      tell(" isn't connected to any");
    } else {
      tell(" looks confused. \"I don't know anything about any");
    }
    await NOT_HERE_PRINT();
    tell("!");
    if (person$) {
      tell("\"");
    }
    crlf();
    return true;
  } else if (!prso$) {
    tell("You wouldn't find any");
    await NOT_HERE_PRINT();
    tell(" there.\n");
    return true;
  } else {
    return NOT_HERE_OBJECT;
  }
}

async function NOT_HERE_PRINT() {
  if (g.P_OFLAG || g.P_MERGED) {
    if (g.P_XADJ) {
      tell(" ");
      printB(g.P_XADJN);
    }
    if (g.P_XNAM) {
      tell(" ");
      return printB(g.P_XNAM);
    } else {
      return false;
    }
  } else if (g.PRSO == NOT_HERE_OBJECT) {
    return await BUFFER_PRINT(get(g.P_ITBL, P_NC1), get(g.P_ITBL, P_NC1L), false);
  } else {
    return await BUFFER_PRINT(get(g.P_ITBL, P_NC2), get(g.P_ITBL, P_NC2L), false);
  }
}

