async function AIRLOCK_F(rarg = false) {
  if (rarg == M_ENTER) {
    if (g.GREENUP_ESCAPE || g.GREENUP_TRAPPED) {
      move(LOWELL, g.HERE);
      move(ANTRIM, g.HERE);
      tell("Two of the crew are with you.\n");
      return true;
    } else {
      return false;
    }
  } else if (rarg == M_LOOK) {
    tell("You're now in the ", D(AIRLOCK), ", at the foot of the ramp.\n");
    return true;
  } else if (rarg) {
    return false;
  } else if ((await REMOTE_VERB$()) && !(isVerb(V.THROUGH, V.WALK_TO))) {
    return false;
  } else if (!g.SUB_IN_DOME && !(await SUB_OUTSIDE_AIRLOCK$())) {
    return await NOT_HERE(AIRLOCK);
  } else if (isVerb(V.EMPTY)) {
    if (!g.AIRLOCK_FULL) {
      return (await ALREADY(AIRLOCK, "empty"));
    } else if (hasFlag(AIRLOCK_HATCH, OPENBIT)) {
      return (await YOU_CANT(false, AIRLOCK_HATCH, "open"));
    } else if ((g.HERE == SUB || g.HERE == CRAWL_SPACE) || (g.HERE == BLY_OFFICE || g.HERE == FOOT_OF_RAMP)) {
      enable(await QUEUE(I_AIRLOCK_EMPTY.id, 2));
      tell("This will take 1 turn.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.FILL)) {
    if (g.AIRLOCK_FULL) {
      (await ALREADY(AIRLOCK, "full"));
      return true;
    } else if (!(hasFlag(AIRLOCK_ELECTRICITY, ONBIT))) {
      (await YOU_CANT(false, AIRLOCK_ELECTRICITY, "off"));
      return true;
    } else if (await AIRLOCK_POP$()) {
      (await YOU_CANT(false, AIRLOCK, "full of people"));
      return true;
    }
    if (!g.GREENUP_ESCAPE) {
      if (hasFlag(SUB_DOOR, OPENBIT)) {
        (await YOU_CANT(false, SUB_DOOR, "open"));
        return true;
      }
      if (hasFlag(AIRLOCK_ROOF, OPENBIT)) {
        await THIS_IS_IT(AIRLOCK_ROOF);
        tell("A safety mechanism prevents it. The ", D(AIRLOCK_ROOF), " is open!\n");
        return true;
      }
    }
    if (g.GREENUP_ESCAPE && (4 > g.GREENUP_ESCAPE)) {
      tell("Greenup is frantically scrambling back up the ladder to avoid being swept off and drowned! ");
      await GREENUP_CUFF();
      tell("Tip immediately empties the ", D(AIRLOCK), " again.\n");
      return true;
    } else if ((g.HERE == SUB || g.HERE == CRAWL_SPACE) || (g.HERE == BLY_OFFICE || g.HERE == FOOT_OF_RAMP)) {
      enable(await QUEUE(I_AIRLOCK_EMPTY.id, 2));
      tell("This will take 1 turn.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    await PERFORM(g.PRSA, AIRLOCK_HATCH);
    return true;
  } else if (isVerb(V.THROUGH, V.WALK_TO)) {
    if (!g.SUB_IN_DOME && (g.HERE == SUB || g.HERE == CRAWL_SPACE)) {
      (await TOO_BAD_BUT(g.PRSO, "too far away"));
      return true;
    }
    g.PRSO = AIRLOCK;
    await CHEERS$();
    return false;
  } else {
    return false;
  }
}

