async function HORVAK_LOCKER_F() {
  if (isVerb(V.LOOK_INSIDE) && hasFlag(HORVAK_LOCKER, OPENBIT)) {
    tell("The locker contains mostly clothing, toilet articles and books.");
    if (loc(DIARY) == HORVAK_LOCKER) {
      tell(" One of the books is labeled DIARY.");
      if (loc(PHOTO) == DIARY) {
        clearFlag(PHOTO, INVISIBLE);
        tell(" Something has been inserted between its pages.");
      }
    }
    return crlf();
  } else if (isVerb(V.OPEN, V.OPEN_WITH, V.UNLOCK) && (g.PRSO == HORVAK_LOCKER)) {
    if (hasFlag(HORVAK_LOCKER, OPENBIT)) {
      return false;
    } else if (hasFlag(HORVAK_LOCKER, LOCKED) && !(g.PRSI == UNIVERSAL_TOOL)) {
      await THIS_IS_IT(HORVAK_KEY);
      tell("It's locked. The normal way to open its lock (which you yourself designed, ");
      await PRINT_NAME(g.FIRST_NAME);
      tell(") is with a key.\n");
      return true;
    }
    clearFlag(HORVAK_LOCKER, LOCKED);
    setFlag(HORVAK_LOCKER, OPENBIT);
    setFlag(DIARY, TAKEBIT);
    await PERFORM(V.LOOK_INSIDE, HORVAK_LOCKER);
    return true;
  } else {
    return false;
  }
}

async function HORVAK_KEY_F() {
  if (((g.PRSI == HORVAK) && isVerb(V.TAKE)) || ((g.PRSO == HORVAK) && isVerb(V.ASK_FOR, V.SEARCH_FOR))) {
    if (g.WINNER == PLAYER) {
      tell("Be warned, ");
      await PRINT_NAME(g.FIRST_NAME);
      tell(", that he will never willingly surrender it. You have no right to demand it without a search warrant. The ", D(AQUADOME), " is neither a military establishment nor a ship at sea, so you could get in legal trouble.\n");
      return true;
    } else {
      (await HE_SHE_IT(g.WINNER, true, "refuse"));
      tell(", ");
      await PRINT_NAME(g.FIRST_NAME);
      tell(". Do not pursue this any further, or you will lose the respect and cooperation of the ", D(CREW), ", and thereby abort your rescue mission. If you attempt to use force, they may even mutiny and place you under arrest.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function DIARY_F() {
  if (isVerb(V.OPEN) && !(hasFlag(DIARY, OPENBIT)) && (loc(PHOTO) == DIARY)) {
    setFlag(DIARY, OPENBIT);
    move(PHOTO, g.HERE);
    tell("As you do so, a picture falls out. Oh, oh! It's a snapshot of Zoe Bly!\n");
    return true;
  } else if (isVerb(V.READ, V.LOOK_INSIDE)) {
    if (!(hasFlag(DIARY, OPENBIT))) {
      tell("You must open it first.\n");
      return true;
    } else {
      tell("You quickly discover references to Zoe Bly. It seems clear that ", D(HORVAK), " has fallen for Zoe. But her unsentimental manner is a large obstacle.\nThe last entry reads:\n\"If only I could find some way to break down that icy reserve of Zoe's, and make her realize she's not just a scientific thinking machine or a commanding officer...!\nThere must be some way! She doesn't do everything by the rule book. She even breaks regulations at times. If I can prove this and embarrass her, maybe she'll realize she's just a human being like the rest of us -- and not only a human being, but a warm, desirable woman...!\"\n");
      if (hasFlag(SPECIAL_TOOL, TOUCHBIT)) {
        tell("\nWell! It sounds as if ", D(HORVAK), " found the answer to his problem by sabotaging the ", D(AIR_SUPPLY_SYSTEM), " -- at a time when ", D(BLY), " was breaking regulations by not wearing her ", D(OXYGEN_GEAR), "!\n");
      }
      return true;
    }
  } else {
    return false;
  }
}

