async function DOME_LAB_F(rarg = false, magloc = 0) {
  if (rarg == M_LOOK) {
    tell("The ", D(DOME_LAB), " is equipped for all sorts of marine biochemical research. ");
    return await ROOM_IS_CROWDED();
  } else if ((rarg == M_ENTER) && !(hasFlag(AIR_SUPPLY_SYSTEM, MUNGBIT))) {
    if (!(loc(BLY) == DOME_LAB)) {
      move(BLY, DOME_LAB);
      tell(D(BLY), " comes too.\n");
    }
    if (!(hasFlag(HORVAK, BUSYBIT)) && !(loc(HORVAK) == DOME_LAB)) {
      move(HORVAK, DOME_LAB);
      tell(D(HORVAK), " comes too.\n");
    }
    if (g.HORVAK_TOLD_AH || !(hasFlag(DART, MUNGBIT)) || hasFlag(HORVAK, BUSYBIT)) {
      return true;
    }
    g.HORVAK_TOLD_AH = true;
    tell("\n", D(HORVAK), " says:\n\"");
    await PRINT_NAME(g.FIRST_NAME);
    tell(", right after the Snark ceased its attack, I detected a high concentration of A.H. molecules in the ", D(GLOBAL_WATER), " around the ", D(AQUADOME), ". Have you ever heard of such a phenomenon before?\"");
    if (!(await YES$())) {
      tell("\"I can make up an intense tranquilizer to subdue the ", D(SNARK), ",\" ", D(HORVAK), " continues. \"You could use one of our aquatic dart guns to inject it into the creature. You could mount the gun on one of the ", D(SUB), "'s ", D(CLAW), "s.\nBut without knowing the creature's biochemistry, there's no guarantee the 'trank' will work. Shall I go ahead and make some up, anyhow?\"");
      magloc = await YES$();
    }
    magloc = await META_LOC(MAGAZINE);
    if (!(await IN_DOME$(magloc))) {
      return true;
    }
    await TIP_SAYS();
    tell("Wait a minute! Wasn't there something about A.H. molecules in that ", D(MAGAZINE), "? Shall ");
    if (magloc == g.HERE) {
      tell("we");
    } else {
      tell("I get it and");
    }
    tell(" see?\"");
    await THIS_IS_IT(MAGAZINE);
    if (await YES$()) {
      if (!(loc(MAGAZINE) == PLAYER)) {
        move(MAGAZINE, PLAYER);
        tell("Tip ");
        if (!(magloc == g.HERE)) {
          tell("returns quickly and ");
        }
        tell("hands you the ", D(MAGAZINE), ". ");
      }
      await THIS_IS_IT(HORVAK);
      tell(D(HORVAK), " looks interested. \"I'd like to see that.\"\n");
    }
    return true;
  } else {
    return false;
  }
}

