async function READ_NAME(tbl, str) {
  let ptr = 0, len = 0, n_ = 0, numtokens = 0, tok = 0;
  restart: for (;;) {
    tell(S(str), "\n");
    tell(">");
    await read(g.P_INBUF, g.P_LEXV);
    if (getb(g.P_LEXV, P_LEXWORDS) == 0) {
      tell("I beg your pardon?\n");
      continue restart;
    }
    if (!((n_ = get(g.P_LEXV, P_LEXSTART)) == 0)) {
      if (ACT.RESTART == (n_ = await WT$(n_, PS$VERB, P1$VERB))) {
        await restart();
        tell(S(g.FAILED), "\n");
        continue restart;
      } else if (n_ == ACT.$VERIFY) {
        await V_$VERIFY();
        continue restart;
      } else if (n_ == ACT.RELEASE) {
        await V_VERSION();
        continue restart;
      } else if (n_ == ACT.RESTORE) {
        if (await V_RESTORE()) {
          return M_FATAL;
        } else {
          continue restart;
        }
      }
    }
    numtokens = getb(g.P_LEXV, 1);
    tok = numtokens;
    g.NAME_OUTLEN = 1;
    n_ = 2 * (1 + P_LEXSTART);
    loop1: for (;;) {
      if (--tok < 0) {
        break loop1;
      }
      len = getb(g.P_LEXV, n_);
      ptr = getb(g.P_LEXV, 1 + n_);
      await READ_NAME_REPEAT(tbl, ptr, len);
      if (g.NAME_OUTLEN > NAME_LENGTH) {
        break loop1;
      }
      putb(tbl, g.NAME_OUTLEN, 32);
      if (++g.NAME_OUTLEN > NAME_LENGTH) {
        break loop1;
      }
      if (tbl == g.FIRST_NAME) {
        if (!g.FN_SPACE) {
          g.FN_SPACE = g.NAME_OUTLEN - 1;
        }
      } else if (!g.LN_SPACE) {
        g.LN_SPACE = g.NAME_OUTLEN - 1;
      }
      n_ = 4 + n_;
    }
    if (g.NAME_OUTLEN > NAME_LENGTH) {
      putb(tbl, 0, NAME_LENGTH);
    } else {
      putb(tbl, 0, g.NAME_OUTLEN - 2);
    }
    return true;
  }
}

async function READ_NAME_REPEAT(tbl, ptr, len) {
  let ch = 0;
  for (;;) {
    ch = getb(g.P_INBUF, ptr);
    if (--len < 0) {
      return true;
    }
    if (!(ch == 45 || ch == 39 || ch == 38)) {
      ch = 96 + mod(ch, 32);
    }
    putb(tbl, g.NAME_OUTLEN, ch);
    if (++g.NAME_OUTLEN > NAME_LENGTH) {
      return true;
    }
    ptr = 1 + ptr;
  }
}

async function PRINT_NAME(tbl, cap = false) {
  let ptr = 0, len = 0, ch = 0, sp$ = true;
  len = getb(tbl, 0);
  for (;;) {
    if (++ptr > len) {
      return true;
    }
    ch = getb(tbl, ptr);
    if ((cap || sp$) && !(ch == 32 || ch == 45 || ch == 39) && !(ch == 38)) {
      printC(ch - 32);
    } else {
      printC(ch);
    }
    if (ch == 32 || ch == 45 || ch == 39) {
      sp$ = true;
    } else if (ch == 38) {
      sp$ = true;
    } else {
      sp$ = false;
    }
  }
}

async function NAME$(ptr) {
  return (await XNAME$(ptr, g.FIRST_NAME, g.FN_SPACE)) || (await XNAME$(ptr, g.LAST_NAME, g.LN_SPACE));
}

async function XNAME$(ptr, tbl, max) {
  let cnt = 0, bptr = 0, chr = 0, n$ = true, ncnt = 0;
  cnt = getb(g.P_LEXV + (ptr * 2), 2);
  if (cnt > 6) {
    cnt = 6;
  }
  bptr = getb(g.P_LEXV + (ptr * 2), 3);
  if (!max) {
    max = getb(tbl, 0);
  }
  if (!(--max < 7)) {
    max = 6;
  }
  loop1: for (;;) {
    if (++ncnt > max) {
      if (!(cnt == 0)) {
        n$ = false;
      }
      break loop1;
    } else if ((cnt = cnt - 1) < 0) {
      n$ = false;
      break loop1;
    } else {
      chr = getb(g.P_INBUF, bptr);
      if (!(chr == 45 || chr == 38 || chr == 39)) {
        chr = 96 + mod(chr, 32);
      }
      if (!(chr == getb(tbl, ncnt))) {
        n$ = false;
      }
      bptr = bptr + 1;
    }
  }
  if (n$) {
    if (tbl == g.FIRST_NAME) {
      put(g.P_LEXV, ptr, W.$FN);
      return W.$FN;
    } else {
      put(g.P_LEXV, ptr, W.$LN);
      return W.$LN;
    }
  } else {
    return false;
  }
}

