async function COMPUTESTOR_F() {
  if (isVerb(V.TAKE, V.WALK_TO, V.LOOK_BEHIND, V.LOOK_INSIDE, V.LOOK_ON, V.LOOK_UNDER)) {
    return false;
  } else if (isVerb(V.EXAMINE)) {
    tell("The ", D(COMPUTESTOR), " is o", S((hasFlag(COMPUTESTOR, ONBIT) ? "n" : "ff")), ".\n");
    return true;
  } else if (isVerb(V.LAMP_ON)) {
    if (!(hasFlag(COMPUTESTOR, ONBIT))) {
      setFlag(COMPUTESTOR, ONBIT);
      tell("The ", D(COMPUTESTOR), " is ready for questions.\n");
      return true;
    } else {
      return false;
    }
  } else if ((await REMOTE_VERB$()) && (!(isVerb(V.ASK_ABOUT)) || !(g.PRSO == COMPUTESTOR))) {
    return false;
  } else if (!(hasFlag(COMPUTESTOR, ONBIT))) {
    tell("The ", D(COMPUTESTOR), " is off!\n");
    return true;
  } else if (isVerb(V.ASK, V.USE)) {
    if (hasFlag(VIDEOPHONE, MUNGBIT)) {
      await PERFORM(V.ASK_ABOUT, COMPUTESTOR, VIDEOPHONE);
      return true;
    } else if (!(loc(CATALYST_CAPSULE) == REACTOR)) {
      await PERFORM(V.ASK_ABOUT, COMPUTESTOR, GLOBAL_SUB);
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.ASK_ABOUT) && (g.PRSO == COMPUTESTOR)) {
    if ((g.PRSI == CIRCUIT_BREAKER) && hasFlag(CIRCUIT_BREAKER, OPENBIT)) {
      tell("\"A ", D(CIRCUIT_BREAKER), " is open.\"\n");
      return true;
    } else if ((g.PRSI == VIDEOPHONE) && hasFlag(VIDEOPHONE, MUNGBIT)) {
      g.TIP_SAYS_1 = 32;
      g.TIP_SAYS_2 = VIDEOPHONE;
      enable(await QUEUE(I_TIP_SAYS.id, 3));
      tell("\"Symptoms: no picture, no sound.\nPossible causes:\n1) Failure of the ", D(VIDEOPHONE_TRANSMITTER), " at source.\n2) A short in the ", D(VIDEOPHONE_CABLE), " linking ", D(VIDEOPHONE_TRANSMITTER), " to");
      await RESEARCH_LAB();
      tell(", if signal is coming from ", D(AQUADOME), ".\n3) Sunspot interference or ", D(VIDEOPHONE_SATELLITE), " malfunction if ", D(VIDEOPHONE_TRANSMITTER), " is at earth's surface.\n4) Failure of the video receiver.\n5) Overload in the ", D(ELECTRICAL_CONTROL_PANEL), " (", D(CIRCUIT_BREAKER), " popped).\n6) Sabotage (", D(CIRCUIT_BREAKER), " open).\"\n");
      return true;
    } else if ((g.PRSI == VIDEOPHONE_TRANSMITTER) && hasFlag(VIDEOPHONE, MUNGBIT)) {
      tell("Impossible. It's located ", D(UNDERWATER), " at the ", D(AQUADOME), ", beyond your control. Right now you have no communication with the ", D(AQUADOME), ".\n");
      return true;
    } else if (g.PRSI == VIDEOPHONE_CABLE) {
      tell("This can be done only by submarine.\n");
      return true;
    } else if (g.PRSI == VIDEOPHONE_SATELLITE) {
      tell("You're goofing off, ");
      await PRINT_NAME(g.FIRST_NAME);
      tell(". Video signals from the ", D(AQUADOME), " to");
      await RESEARCH_LAB();
      tell(" are NOT relayed by a space ", D(VIDEOPHONE_SATELLITE), ".\n");
      return true;
    } else if (g.PRSI == VIDEOPHONE_RECEIVER) {
      tell("You can do this by pushing the ", D(TEST_BUTTON), " on the ", D(VIDEOPHONE), ".\n");
      return true;
    } else if ((g.PRSI == REACTOR || g.PRSI == GLOBAL_SUB) && !(loc(CATALYST_CAPSULE) == REACTOR)) {
      tell("\"Symptom: ", D(ENGINE), " won't start.\nPossible causes:\n1) The ", D(CATALYST_CAPSULE), " is not inserted in the ", D(REACTOR), ".\n2) The ", D(REACTOR), " is not turned on.\n3) The ", D(TEST_TANK), " is not filled.\"\n");
      return true;
    } else {
      tell("\"This device is designed only to troubleshoot operating problems.\"\n(Maybe you can find information about");
      await THE_PRSI_PRINT();
      tell(" in your SEASTALKER package.)\n");
      return true;
    }
  } else {
    return false;
  }
}

