async function MICROPHONE_F(dome$ = false) {
  if (isVerb(V.EXAMINE)) {
    tell("The ", D(MICROPHONE), " is connected to the ", D(VIDEOPHONE), " by a coiled cord. At the moment, it is turned o");
    if ((dome$ && hasFlag(MICROPHONE_DOME, ONBIT)) || (!dome$ && hasFlag(MICROPHONE, ONBIT))) {
      tell("n.\n");
      return true;
    } else {
      tell("ff.\n");
      return true;
    }
  } else if ((isVerb(V.LAMP_OFF) || (await DIVESTMENT$(MICROPHONE)) || (await DIVESTMENT$(MICROPHONE_DOME))) && (g.PRSO == MICROPHONE_DOME || g.PRSO == MICROPHONE) && (VIDEOPHONE == g.REMOTE_PERSON_ON)) {
    tell("You'd better say \"Good-bye\" to ", D(g.REMOTE_PERSON), " first.\n");
    return true;
  } else if (isVerb(V.REPLY, V.SAY_INTO) && !(hasFlag(VIDEOPHONE, ONBIT))) {
    tell("That won't do any good while the ", D(VIDEOPHONE), " is off.\n");
    return true;
  } else if (isVerb(V.SAY_INTO)) {
    if (g.REMOTE_PERSON_ON == VIDEOPHONE) {
      tell(D(g.REMOTE_PERSON), " nods at you.\n");
      return true;
    } else if (g.WOMAN_ON_SCREEN) {
      tell("That won't do any good while the sound is fuzzy.\n");
      return true;
    } else {
      tell("It's not clear whom you're talking to.\n");
      return true;
    }
  } else if (isVerb(V.LAMP_ON) && ((loc(MICROPHONE) == PLAYER) || (loc(MICROPHONE_DOME) == PLAYER))) {
    if ((dome$ && hasFlag(MICROPHONE_DOME, ONBIT)) || (!dome$ && hasFlag(MICROPHONE, ONBIT))) {
      (await ALREADY(MICROPHONE, "on"));
      return true;
    }
    if (dome$) {
      return (await OKAY(MICROPHONE_DOME, "on"));
    } else {
      return (await OKAY(MICROPHONE, "on"));
    }
  } else {
    return false;
  }
}

