async function LOCAL_SUB_F() {
  if (isVerb(V.PUT, V.TURN)) {
    return await MORE_SPECIFIC();
  } else if (isVerb(V.SEARCH, V.SEARCH_FOR)) {
    await DO_INSTEAD_OF(SUB, LOCAL_SUB);
    return true;
  } else if (isVerb(V.EXAMINE)) {
    if (!(get(g.ON_SUB, 0)) && !(get(g.ON_SUB, 1))) {
      tell(S(getProp(LOCAL_SUB, P.TEXT)), "\n");
      return true;
    }
    if (get(g.ON_SUB, 0)) {
      await MIKE_3_F(get(g.ON_SUB, 0));
    }
    if (get(g.ON_SUB, 1)) {
      await MIKE_3_F(get(g.ON_SUB, 1));
    }
    return true;
  } else if (isVerb(V.FIND)) {
    disable(await INT(I_SEND_SUB.id));
    tell("It's right here!\n");
    return true;
  } else if (isVerb(V.LOOK_BEHIND) || (isVerb(V.LOOK_OUTSIDE) && (g.HERE == SUB))) {
    await PERFORM(V.LOOK_OUTSIDE, SUB_WINDOW);
    return true;
  } else if (isVerb(V.LOOK_INSIDE)) {
    if (g.HERE == SUB || g.HERE == CRAWL_SPACE) {
      await PERFORM(V.LOOK);
      return true;
    } else {
      tell("You can't see much from here.\n");
      return true;
    }
  } else if (isVerb(V.SEND, V.SEND_OUT, V.SEND_TO) && (g.PRSO == LOCAL_SUB)) {
    return await CANT_SEND();
  } else if (isVerb(V.THROUGH, V.BOARD)) {
    if (g.HERE == SUB || g.HERE == CRAWL_SPACE) {
      return (await ALREADY(g.WINNER, "in it"));
    } else if (g.HERE == AIRLOCK_WALL) {
      if (await GOTO(AIRLOCK)) {
        if ((await GOTO(SUB)) && !(g.WINNER == PLAYER)) {
          await OKAY();
        }
        return true;
      } else {
        return false;
      }
    } else if (g.HERE == WEST_TANK_AREA || g.HERE == SOUTH_TANK_AREA) {
      tell(S(getProp(WEST_TANK_AREA, P.EAST)), "\n");
      return true;
    } else {
      await DO_WALK(P.IN);
      return true;
    }
  } else if (isVerb(V.DISEMBARK, V.DROP, V.RAISE)) {
    if (!(g.HERE == SUB || g.HERE == CRAWL_SPACE)) {
      tell("You're not in it!\n");
      return true;
    } else if (isVerb(V.DROP)) {
      await DO_WALK(P.DOWN);
      return true;
    } else if (isVerb(V.RAISE)) {
      await DO_WALK(P.UP);
      return true;
    } else {
      await DO_WALK(P.OUT);
      return true;
    }
  } else if (isVerb(V.OPEN, V.CLOSE) && !(g.HERE == CRAWL_SPACE || g.HERE == AIRLOCK_WALL)) {
    await PERFORM(g.PRSA, SUB_DOOR);
    return true;
  } else if (isVerb(V.ANALYZE) && (g.PRSI == DAMAGE || g.PRSI == GLOBAL_SABOTAGE || g.PRSI == false)) {
    tell("You can do this by pushing the ", D(TEST_BUTTON));
    if (!(g.HERE == SUB || g.HERE == CRAWL_SPACE)) {
      tell(" on the ", D(CONTROLS), " inside");
    }
    tell(".\n");
    return true;
  } else if (isVerb(V.LAMP_ON)) {
    if (!(g.HERE == SUB)) {
      await THIS_IS_IT(SUB);
      tell("You have to be in the ", D(SUB), " to start it.\n");
      return true;
    } else if (!(hasFlag(REACTOR, ONBIT))) {
      await THIS_IS_IT(REACTOR);
      tell("The reactor is off!\n");
      return true;
    } else if ((g.SUB_IN_TANK && !g.TEST_TANK_FULL && (await THIS_IS_IT(TEST_TANK))) || (g.SUB_IN_DOME && !g.AIRLOCK_FULL && (await THIS_IS_IT(AIRLOCK)))) {
      tell("The tank is empty!\n");
      return true;
    } else if ((g.SUB_IN_TANK && !(hasFlag(TANK_GATE, OPENBIT)) && (await THIS_IS_IT(TANK_GATE))) || (g.SUB_IN_DOME && !(hasFlag(AIRLOCK_HATCH, OPENBIT)) && (await THIS_IS_IT(AIRLOCK_HATCH)))) {
      tell("The gate is closed!\n");
      return true;
    } else if (!(hasFlag(ENGINE, ONBIT))) {
      await THIS_IS_IT(ENGINE);
      tell("The engine is off!\n");
      return true;
    } else {
      tell("You can do this by setting the throttle to the speed you want (slow, medium, or fast) and by moving the ", D(JOYSTICK), " in the ", D(INTDIR), " you wish to go.\n");
      return true;
    }
  } else if (isVerb(V.STOP)) {
    if (!(g.HERE == SUB)) {
      await THIS_IS_IT(SUB);
      tell("You have to be in the ", D(SUB), " to stop it.\n");
      return true;
    } else if (!(hasFlag(ENGINE, ONBIT))) {
      tell("The engine is off!\n");
      return true;
    } else {
      g.TARGET_DEPTH = g.SUB_DEPTH;
      tell(S(g.I_ASSUME), " close the ", D(THROTTLE), ".)\n");
      await PERFORM(V.CLOSE, THROTTLE);
      return true;
    }
  } else {
    return false;
  }
}

