async function TEST_BUTTON_F() {
  if (isVerb(V.PUSH, V.TURN, V.LAMP_OFF, V.LAMP_ON)) {
    if (g.HERE == CENTER_OF_LAB) {
      if (hasFlag(VIDEOPHONE, MUNGBIT)) {
        await TELL_HINT(83, POWER_SUPPLY, false);
      } else if (g.P_XADJN == W.TEST) {
        await A_O_K();
      } else if (loc(MICROPHONE) == PLAYER) {
        if (isVerb(V.LAMP_OFF, V.LAMP_ON)) {
          await PERFORM(g.PRSA, MICROPHONE);
        } else if (hasFlag(MICROPHONE, ONBIT)) {
          await PERFORM(V.LAMP_OFF, MICROPHONE);
        } else {
          await PERFORM(V.LAMP_ON, MICROPHONE);
        }
      } else if (isVerb(V.LAMP_OFF)) {
        await PERFORM(V.LAMP_OFF, VIDEOPHONE);
      } else {
        await PERFORM(V.LAMP_ON, VIDEOPHONE);
      }
      return true;
    } else if (g.HERE == SUB || g.HERE == CRAWL_SPACE) {
      if (g.TEST_BUTTON_READOUT) {
        tell("Readout display says:\n");
        if (g.TEST_BUTTON_READOUT == TEST_BUTTON_NORMAL) {
          await A_O_K();
          return true;
        } else if (g.TEST_BUTTON_READOUT == GATE_CRASHED_MSG) {
          tell("No damage. Hull still watertight.");
        } else if (g.TEST_BUTTON_READOUT == REGULATOR_MSG) {
          g.REGULATOR_MSG_SEEN = true;
          tell("Lasers in operational computers are over-charging.\nTo correct, adjust ", D(VOLTAGE_REGULATOR), ".\nWARNING: ", D(VOLTAGE_REGULATOR), " is reachable only from ", D(CRAWL_SPACE), ", behind the ", D(ENGINE_ACCESS_HATCH), ". This is a hazardous operation at sea!");
        } else if (g.TEST_BUTTON_READOUT == TEST_BUTTON_POD) {
          tell(D(ESCAPE_POD_UNIT), " is not properly connected.");
        } else if (g.TEST_BUTTON_READOUT == CLAW_MUNGED_MSG) {
          tell("The ", D(CLAW), " is damaged.");
        }
        return crlf();
      } else {
        return false;
      }
    } else if (g.P_XADJN == W.TEST) {
      return await A_O_K();
    } else if (g.HERE == EAST_WALL) {
      if (isVerb(V.LAMP_OFF)) {
        await PERFORM(V.LAMP_OFF, MICROWAVE_SECURITY_SCANNER);
      } else {
        await PERFORM(V.LAMP_ON, MICROWAVE_SECURITY_SCANNER);
      }
      return true;
    } else if (g.HERE == NORTH_WALL) {
      if (isVerb(V.LAMP_OFF)) {
        await PERFORM(V.LAMP_OFF, COMPUTESTOR);
      } else {
        await PERFORM(V.LAMP_ON, COMPUTESTOR);
      }
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

