async function GLOBAL_HERE_F() {
  let flg = false, f = 0, hr = 0, tim = 0, val = 0;
  if (isVerb(V.KNOCK)) {
    tell("Knocking on the walls reveals nothing unusual.\n");
    return true;
  } else if (isVerb(V.PUT, V.TIE_TO)) {
    return await MORE_SPECIFIC();
  } else if (isVerb(V.SEARCH, V.EXAMINE)) {
    if (!(getProp(g.HERE, P.CORRIDOR) == 0)) {
      tim = 3;
    } else {
      tim = 2 + getProp(g.HERE, P.SIZE);
    }
    if (g.P_ADVERB == W.CAREFULLY) {
      tim = 2 * tim;
    }
    tell("(It's better to examine or search one thing at a time. It would take a long time to search a whole room or area thoroughly. A ");
    if (g.P_ADVERB == W.CAREFULLY) {
      tell("careful");
    } else {
      tell("brief");
    }
    tell(" search would take ", N(tim), " turns, and it might not reveal much. Would you like to do it anyway?)");
    if (await YES$()) {
      if (M_FATAL == (val = await INT_WAIT(tim))) {
        return true;
      } else if (val) {
        tell("Your ", S((g.P_ADVERB == W.CAREFULLY ? "careful" : "brief")), " search reveals nothing exciting.\n");
        return true;
      } else {
        tell("You didn't finish looking over the place.\n");
        return true;
      }
    } else {
      tell("Okay.\n");
      return true;
    }
  } else if (isVerb(V.WHAT, V.ANALYZE)) {
    f = first(g.HERE);
    loop1: for (;;) {
      if (!f) {
        break loop1;
      } else if (hasFlag(f, CONTBIT) && (await INHABITED$(f))) {
        flg = true;
        hr = g.HERE;
        g.HERE = f;
        await GLOBAL_HERE_F();
        g.HERE = hr;
      } else if (hasFlag(f, PERSON) && !(f == PLAYER)) {
        flg = true;
        await DESCRIBE_OBJECT(f, true, 0);
      }
      f = next(f);
    }
    if (!flg) {
      tell("There's nobody else here.\n");
    }
    return true;
  } else {
    return false;
  }
}

