async function OPEN_CLOSE_GATE(gate, full, tank) {
  if (isVerb(V.OPEN, V.RAISE)) {
    if (hasFlag(gate, OPENBIT)) {
      (await ALREADY(gate, "open"));
      return true;
    } else if (!full) {
      tell("You'd better fill the ", D(tank), " first, unless you want to go surfing!\n");
      return true;
    } else {
      if ((gate == TANK_GATE) && (g.HERE == SUB)) {
        g.OPENED_GATE_FROM_SUB = true;
      }
      setFlag(gate, OPENBIT);
    }
  } else {
    if (hasFlag(gate, OPENBIT)) {
      clearFlag(gate, OPENBIT);
    } else {
      (await ALREADY(gate, "closed"));
      return true;
    }
  }
  if (hasFlag(gate, OPENBIT)) {
    tell("Opened");
  } else {
    tell("Closed");
  }
  if (g.HERE == SUB) {
    tell(" (by remote control)");
  }
  tell(".\n");
  return true;
}

