async function DESCRIBE_OBJECT(obj, v$, level) {
  let str = false, av = 0, no_cr = false;
  await THIS_IS_IT(obj);
  if ((level == 0) && (await apply(getProp(obj, P.DESCFCN), M_OBJDESC))) {
    return true;
  }
  if ((level == 0) && ((!(hasFlag(obj, TOUCHBIT)) && (str = getProp(obj, P.FDESC))) || (str = getProp(obj, P.LDESC)))) {
    tell(S(str));
  } else if (level == 0) {
    if (hasFlag(obj, PERSON)) {
      if ((await IS_CREW$(obj)) && (await CREW_5_TOGETHER$()) && !(hasFlag(BLY, MUNGBIT))) {
        if (obj == LOWELL) {
          tell("The five ", D(CREW), " members are here.");
        } else {
          no_cr = true;
        }
      } else {
        tell(D(obj), " is here.");
      }
    } else {
      tell("There's ");
      await PRINTA(obj);
      tell(" here.");
    }
  } else {
    tell(S(get(g.INDENTS, level)));
    if (hasFlag(obj, PERSON)) {
      if ((await IS_CREW$(obj)) && (await CREW_5_TOGETHER$()) && !(hasFlag(BLY, MUNGBIT))) {
        if (obj == LOWELL) {
          tell("the five ", D(CREW), " members");
        } else {
          no_cr = true;
        }
      } else {
        tell(D(obj));
      }
    } else {
      await PRINTA(obj);
    }
    if ((obj == OXYGEN_GEAR) && (loc(OXYGEN_GEAR) == PLAYER)) {
      tell(" (being worn)");
    }
  }
  if ((level == 0) && (av = loc(g.WINNER)) && hasFlag(av, VEHBIT)) {
    tell(" (outside");
    await PRINTT(av);
    tell(")");
  }
  if (!no_cr) {
    crlf();
  }
  if ((await SEE_INSIDE$(obj)) && first(obj)) {
    return await PRINT_CONT(obj, v$, level);
  } else {
    return false;
  }
}

