async function DESCRIBE_ROOM(look$ = false) {
  let v$ = 0, str = 0, l = 0;
  v$ = look$ || g.VERBOSE;
  if (!(hasFlag(g.HERE, TOUCHBIT))) {
    v$ = true;
  }
  if (loc(g.HERE) == ROOMS) {
    tell("(", D(g.HERE), ")\n");
  }
  if (look$ || !g.SUPER_BRIEF) {
    if (hasFlag(l = loc(g.WINNER), VEHBIT)) {
      tell("(You're ");
      if (hasFlag(l, SURFACEBIT)) {
        tell("sitting o");
      } else {
        tell("standing i");
      }
      tell("n");
      await PRINTT(l);
      tell(".)\n");
    }
    if (v$ && (await apply(getProp(g.HERE, P.ACTION), M_LOOK))) {
      setFlag(g.HERE, TOUCHBIT);
      return true;
    } else if (v$ && (str = getProp(g.HERE, P.FDESC))) {
      tell(S(str), "\n");
    } else if (v$ && (str = getProp(g.HERE, P.LDESC))) {
      tell(S(str), "\n");
    } else {
      await apply(getProp(g.HERE, P.ACTION), M_FLASH);
    }
    if (!(g.HERE == l)) {
      await apply(getProp(l, P.ACTION), M_LOOK);
    }
  }
  if (getProp(g.HERE, P.CORRIDOR)) {
    await CORRIDOR_LOOK();
  }
  setFlag(g.HERE, TOUCHBIT);
  return true;
}

