async function LKP(itm, tbl) {
  let cnt = 0, len = get(tbl, 0);
  for (;;) {
    if ((cnt = cnt + 1) > len) {
      return false;
    } else if (eq(get(tbl, cnt), itm)) {
      if (cnt == len) {
        return false;
      } else {
        return get(tbl, cnt + 1);
      }
    }
  }
}

async function GOTO(rm, v$ = true) {
  let l = 0, itarm = 0, ilrm = 0;
  if (loc(g.WINNER) == rm) {
    await HAR_HAR();
    return false;
  }
  if ((await AIR_ROOM$(g.HERE)) && !(await AIR_ROOM$(rm)) && (await BAD_AIR$())) {
    return false;
  }
  if (hasFlag(AIR_SUPPLY_SYSTEM, MUNGBIT) && (rm == DOME_LAB || rm == BLY_OFFICE)) {
    tell("You should wait for someone to invite you.\n");
    return false;
  }
  l = loc(g.WINNER);
  if (g.SUB_IN_DOME && !(hasFlag(AIRLOCK_ROOF, OPENBIT)) && (await THROUGH_ROOF$(rm, l))) {
    await THIS_IS_IT(AIRLOCK_ROOF);
    (await TOO_BAD_BUT(AIRLOCK_ROOF, "closed"));
    return false;
  }
  if (g.WINNER == PLAYER) {
    await TIP_FOLLOWS_YOU(rm);
  } else if (hasFlag(g.WINNER, MUNGBIT)) {
    tell("\"I wish I could!\"\n");
    return false;
  } else if ((rm == CRAWL_SPACE) || ((rm == SUB) && !(g.WINNER == TIP || g.WINNER == SHARON))) {
    tell("\"You belong in there, not I!\"\n");
    return false;
  }
  if (!g.SUB_IN_TANK) {
    await OPEN_DOOR(l);
    await OPEN_DOOR(rm);
  } else {
    itarm = await IN_TANK_AREA$(rm);
    ilrm = await IN_LAB$(rm);
    if (await IN_TANK_AREA$(l)) {
      if (!itarm) {
        setFlag(SOUTH_DOORWAY, OPENBIT);
      }
      if (!ilrm) {
        setFlag(EAST_DOORWAY, OPENBIT);
      }
      if (rm == LAB_STORAGE) {
        setFlag(STORAGE_DOOR, OPENBIT);
      }
    } else if (await IN_LAB$(l)) {
      if (itarm) {
        setFlag(SOUTH_DOORWAY, OPENBIT);
      } else {
        if (!ilrm) {
          setFlag(EAST_DOORWAY, OPENBIT);
        }
        if (rm == LAB_STORAGE) {
          setFlag(STORAGE_DOOR, OPENBIT);
        }
      }
    } else if (l == HALLWAY || l == OFFICE) {
      if (itarm) {
        setFlag(EAST_DOORWAY, OPENBIT);
        setFlag(SOUTH_DOORWAY, OPENBIT);
      }
      if (ilrm) {
        setFlag(EAST_DOORWAY, OPENBIT);
      }
      if (rm == LAB_STORAGE) {
        setFlag(STORAGE_DOOR, OPENBIT);
      }
    } else if (l == LAB_STORAGE) {
      if (itarm) {
        setFlag(EAST_DOORWAY, OPENBIT);
        setFlag(SOUTH_DOORWAY, OPENBIT);
      }
      if (ilrm) {
        setFlag(EAST_DOORWAY, OPENBIT);
      }
      setFlag(STORAGE_DOOR, OPENBIT);
    }
  }
  move(g.WINNER, rm);
  if (g.WINNER == SHARON) {
    if (rm == OFFICE) {
      setFlag(SHARON, NDESCBIT);
      setFlag(FILE_DRAWER, NDESCBIT);
      setFlag(PAPERS, NDESCBIT);
    } else {
      clearFlag(SHARON, NDESCBIT);
      clearFlag(FILE_DRAWER, NDESCBIT);
      clearFlag(PAPERS, NDESCBIT);
    }
  }
  g.LIT = true;
  if (g.WINNER == PLAYER) {
    g.HERE = rm;
    if (v$) {
      await V_FIRST_LOOK();
    }
    await apply(getProp(g.HERE, P.ACTION), M_ENTER);
    await apply(getProp(g.HERE, P.ACTION), M_FLASH);
  }
  return true;
}

