async function PRE_FIND() {
  let chr = 0;
  if (g.PRSO == PLAYER) {
    return false;
  }
  if (loc(g.PRSO) == ROOMS) {
    if (g.PRSO == g.HERE) {
      return (await ALREADY(PLAYER, "here"));
    } else if (hasFlag(g.PRSO, TOUCHBIT)) {
      tell("You should know - you've been there!\n");
      return true;
    } else {
      tell(S(getProp(LOCAL_SUB, P.TEXT)), "\n");
      return true;
    }
  } else if (hasFlag(g.PRSO, PERSON)) {
    if ((g.PRSO == g.REMOTE_PERSON) && g.REMOTE_PERSON_REMLOC) {
      await HE_SHE_IT(g.REMOTE_PERSON, true);
      tell("'s in the ", D(g.REMOTE_PERSON_REMLOC), ".\n");
      return true;
    }
    chr = getProp(g.PRSO, P.CHARACTER);
    if (loc(g.PRSO) == GLOBAL_OBJECTS) {
      g.PRSO = get(g.CHARACTER_TABLE, chr);
    }
    if (!(loc(g.PRSO)) || (await FAR_AWAY$(loc(g.PRSO)))) {
      if ((g.PRSO == BLY) || (await IS_CREW$(g.PRSO))) {
        await HE_SHE_IT(g.PRSO, true);
        tell("'s probably at the ", D(AQUADOME), ".\n");
        return true;
      } else {
        tell("Who knows where ");
        await HE_SHE_IT(g.PRSO);
        tell(" is now?\n");
        return true;
      }
    }
    if (eq(await META_LOC(g.WINNER), await META_LOC(g.PRSO))) {
      if (g.WINNER == PLAYER) {
        await BITE_YOU();
      } else {
        tell("\"Ahem...\"\n");
      }
      return true;
    }
    if (!(g.WINNER == PLAYER)) {
      tell("\"I think ");
      await HE_SHE_IT(g.PRSO);
    } else {
      await HE_SHE_IT(g.PRSO, true);
    }
    tell("'s in");
    await PRINTT(await META_LOC(g.PRSO));
    tell(".");
    if (!(g.WINNER == PLAYER)) {
      tell("\"");
    }
    return crlf();
  } else {
    return false;
  }
}

