async function V_FIND() {
  let l = loc(g.PRSO);
  if (!(PLAYER == g.WINNER)) {
    tell("\"");
  }
  if (g.PRSO == PLAYER) {
    tell("You're right here, ");
    if (hasFlag(l, SURFACEBIT)) {
      tell("on");
    } else {
      tell("in");
    }
    await PRINTT(l);
    tell(".");
  } else if (loc(g.PRSO) == PLAYER) {
    tell("You have it.");
  } else if (loc(g.PRSO) == g.WINNER) {
    tell("\"I have it, ");
    await PRINT_NAME(g.FIRST_NAME);
    tell(".\"");
  } else if (((l == LOCAL_GLOBALS) && (await GLOBAL_IN$(g.PRSO, g.HERE))) || (loc(g.PRSO) == g.HERE) || (g.PRSO == PSEUDO_OBJECT)) {
    tell("It's right here.");
  } else if (l == GLOBAL_OBJECTS || l == LOCAL_GLOBALS) {
    tell("It's around somewhere.");
  } else if (await FAR_AWAY$(await META_LOC(g.PRSO))) {
    tell("It's far away from here.");
  } else if (hasFlag(l, PERSON)) {
    tell(D(l), " has it.");
  } else if (hasFlag(l, SURFACEBIT)) {
    tell("It's on");
    await PRINTT(l);
    tell(".");
  } else if (hasFlag(l, CONTBIT) || (loc(l) == ROOMS)) {
    tell("It's in");
    await PRINTT(l);
    tell(".");
  } else {
    tell("It's nowhere in particular.");
  }
  if (!(PLAYER == g.WINNER)) {
    tell("\"");
  }
  return crlf();
}

