async function SEE_INTO$(there) {
  let p_ = 0, l = 0, tbl = 0, o = 0;
  p_ = 0;
  for (;;) {
    if ((p_ = nextProp(g.HERE, p_)) == 0) {
      tell("You can't seem to find that room.\n");
      return false;
    } else if (p_ == P.IN || p_ == P.OUT) {
      return true;
    } else if (!(p_ < LOW_DIRECTION)) {
      tbl = getPropAddr(g.HERE, p_);
      l = propSize(tbl);
      if ((l == UEXIT) && eq(getb(tbl, REXIT), there)) {
        return true;
      } else if ((l == DEXIT) && eq(getb(tbl, REXIT), there)) {
        if (hasFlag(getb(tbl, DEXITOBJ), OPENBIT)) {
          return true;
        } else {
          tell("The door to that room is closed.\n");
          return false;
        }
      } else if ((l == CEXIT) && eq(getb(tbl, REXIT), there)) {
        if (globalValue(getb(tbl, CEXITFLAG))) {
          return true;
        } else {
          tell("You can't seem to find that room.\n");
          return false;
        }
      }
    }
  }
}

