async function FINISH(repeating = false, val = 0) {
  if (g.DEBUG) {
    return true;
  }
  crlf();
  crlf();
  if (!repeating) {
    await V_SCORE();
    crlf();
  }
  tell("Would you like to:\n   RESTORE your place from where you saved it,\n   RESTART the story from the beginning, or\n   QUIT for now?\n");
  for (;;) {
    tell(">");
    await read(g.P_INBUF, g.P_LEXV);
    val = get(g.P_LEXV, P_LEXSTART);
    if (!(val == 0)) {
      val = await WT$(val, PS$VERB, P1$VERB);
      if (val == ACT.RESTART) {
        await restart();
        await FINISH(true);
      } else if (val == ACT.RESTORE) {
        if (await V_RESTORE()) {
          return true;
        }
        await FINISH(true);
      } else if (val == ACT.QUIT) {
        await quit();
      }
    }
    tell("(Type RESTORE, RESTART, or QUIT.) ");
  }
}

