async function ROB(what, thief) {
  let n_ = 0, x = 0;
  x = first(what);
  for (;;) {
    if (!x) {
      return true;
    }
    n_ = next(x);
    move(x, thief);
    clearFlag(x, TAKEBIT);
    x = n_;
  }
}

