async function TIP_COMES(almost = false) {
  if (g.SIEGEL_TESTED || hasFlag(SIEGEL, BUSYBIT)) {
    return false;
  } else if (g.GREENUP_ESCAPE || g.GREENUP_TRAPPED || g.GREENUP_CUFFED) {
    return false;
  } else if ((g.HERE == SUB || g.HERE == CRAWL_SPACE) || hasFlag(TIP, BUSYBIT)) {
    await QUEUE(I_TIP_SONAR_PLAN.id, 3);
    return false;
  } else if (almost) {
    move(TIP, g.HERE);
    almost = get(await INT(I_TIP_SONAR_PLAN.id), 1);
    if ((almost > (-1)) || eq(mod(0 - almost, 7), 2)) {
      await TIP_SAYS(true);
      await PRINT_NAME(g.FIRST_NAME);
      tell(", I'd like to talk with you alone.\"\n");
      if (almost > (-1)) {
        await QUEUE(I_TIP_SONAR_PLAN.id, -1);
      }
      return true;
    } else {
      return false;
    }
  }
  await QUEUE(I_TIP_SONAR_PLAN.id, 0);
  crlf();
  if (!g.BLACK_BOX_EXAMINED) {
    await TELL_HINT(11, BLACK_BOX);
  }
  move(TIP, g.HERE);
  await TIP_SAYS(true);
  await PRINT_NAME(g.FIRST_NAME);
  tell(", did ", D(BLY), " mention any troublemakers among the ", D(CREW), "?\"");
  if (await YES$()) {
    tell("\"Do you suspect ", D(ANTRIM), " or ", D(HORVAK), " or ", D(SIEGEL), "?\"");
    if (await YES$()) {
      tell("\"Marv maintains the ", D(SONAR_EQUIPMENT), ",\" ");
      await TIP_SAYS();
      tell("and we'll need it to warn us if the ", D(SNARK), " comes back. Didn't Zoe say something is wrong with it?\"");
      if (await YES$()) {
        tell("\"");
        await PRINT_NAME(g.FIRST_NAME);
        tell(", do you think someone tampered with it?\"");
        if (await YES$()) {
          tell("\"Does Marv suspect you've discovered signs of tampering?\"");
          if (!(await YES$())) {
            await THIS_IS_IT(TIP_IDEA);
            tell("\"Then I have an idea how to trap Marv and find out if he's the ", D(TRAITOR), "!\"\n");
          }
        }
      }
    }
  }
  return true;
}

